int Add(int a, int b)
{
    return a + b;
}

void Greet(string name)
{
    Console.WriteLine($"Hello, {name}!");
}

Console.WriteLine(Square(7));
Console.WriteLine(IsEven(10));
Console.WriteLine(ToCelsius(212));

int Square(int n) => n * n;
bool IsEven(int n) => n % 2 == 0;
double ToCelsius(double fahrenheit) => (fahrenheit - 32) * 5 / 9;

Console.WriteLine(Describe("Rex"));
Console.WriteLine(Describe("Tom", species: "cat"));
Console.WriteLine(Describe("Polly", 12, "parrot"));
Console.WriteLine(Describe(age: 3, name: "Bella"));

string Describe(string name, int age = 1, string species = "dog")
    => $"{name} is a {age}-year-old {species}.";

Console.WriteLine(Sum());
Console.WriteLine(Sum(1, 2, 3, 4));

if (TryDivide(10, 4, out double quotient))
{
    Console.WriteLine($"10 / 4 = {quotient}");
}

if (!TryDivide(1, 0, out _))
{
    Console.WriteLine("Cannot divide by zero");
}

int lives = 3;
LoseLife(ref lives);
Console.WriteLine($"Lives left: {lives}");

int Sum(params int[] numbers)
{
    int total = 0;
    foreach (int n in numbers) total += n;
    return total;
}

bool TryDivide(double a, double b, out double result)
{
    if (b == 0)
    {
        result = 0;
        return false;
    }
    result = a / b;
    return true;
}

void LoseLife(ref int count) => count--;

Console.WriteLine($"{Area(5):F2}");
Console.WriteLine(Area(4, 2.5));

double Area(double radius) => Math.PI * radius * radius;
double Area(double width, double height) => width * height;

Console.WriteLine(Factorial(5));
Console.WriteLine(Factorial(20));

long Factorial(int n) => n <= 1 ? 1 : n * Factorial(n - 1);

